public static ABSMRPAssessmentCheckConfig find(ABSMRPCheckCode _checkCode, boolean _forUpdate = false)
{
    ABSMRPAssessmentCheckConfig ret;

    ret.selectForUpdate(_forUpdate);

    select firstonly ret
        where ret.CheckCode == _checkCode;

    return ret;
}

public static boolean isSuppressed(ABSMRPCheckCode _checkCode)
{
    ABSMRPAssessmentCheckConfig cfg = ABSMRPAssessmentCheckConfig::find(_checkCode);
    return cfg.RecId != 0 && cfg.Enabled == NoYes::No;
}

