public void initValue()
{
    super();

    this.Enabled          = NoYes::Yes;
    this.ApplicableEngine = ABSMRPCheckApplicability::Both;
}

public static NoYes getEnabled(ABSMRPCheckCode _checkCode)
{
    ABSMRPAssessmentCheckConfig cfg = ABSMRPAssessmentCheckConfig::find(_checkCode);
    return cfg.RecId ? cfg.Enabled : NoYes::Yes;
}

public static void setEnabled(ABSMRPCheckCode _checkCode, NoYes _enabled)
{
    ABSMRPAssessmentCheckConfig cfg = ABSMRPAssessmentCheckConfig::find(_checkCode, true);

    ttsbegin;

    if (!cfg.RecId)
    {
        cfg.clear();
        cfg.CheckCode = _checkCode;
        cfg.initValue();
    }

    cfg.Enabled = _enabled;

    if (cfg.Enabled == NoYes::No)
    {
        cfg.SuppressedBy   = curUserId();
        cfg.SuppressedDate = today();
    }
    else
    {
        cfg.SuppressedBy   = '';
        cfg.SuppressedDate = dateNull();
        cfg.SuppressReason = '';
    }

    if (cfg.RecId)
        cfg.update();
    else
        cfg.insert();

    ttscommit;
}
